157	    private static final class ShortestPathSolver {
158	        private final Graph graph;
159	        private final Distances distances;
160	        private final PriorityQueue<QueueEntry> minHeap;
161	
162	        private ShortestPathSolver(Graph graph, int source) {
163	            this.graph = graph;
164	            this.distances = Distances.forSource(graph.vertexCount(), source);
165	            this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
166	            minHeap.offer(new QueueEntry(0, source));
167	        }
168	
169	        private static Distances solve(Graph graph, int source) {
170	            return new ShortestPathSolver(graph, source).run();
171	        }
172	
173	        private Distances run() {
174	            while (!minHeap.isEmpty()) {
175	                QueueEntry current = minHeap.poll();
176	                if (distances.isStale(current)) {
177	                    continue;
178	                }
179	
180	                relaxNeighborsOf(current);
181	            }
182	            return distances;
183	        }
184	
185	        private void relaxNeighborsOf(QueueEntry current) {
186	            for (Edge edge : graph.neighborsOf(current.vertex)) {
187	                tryRelax(current, edge);
188	            }
189	        }
190	
191	        private void tryRelax(QueueEntry current, Edge edge) {
192	            int nextDistance = addDistances(current.distance, edge.weight);
193	            if (distances.tryUpdate(edge.to, nextDistance)) {
194	                minHeap.offer(new QueueEntry(nextDistance, edge.to));
195	            }
196	        }
197	    }
