 82	    private final List<List<Edge>> adjacency;
 83	
 84	    private Graph(List<List<Edge>> adjacency) {
 85	        this.adjacency = adjacency;
 86	    }
 87	
 88	    static Graph withVertexCount(int vertexCount) {
 89	        GraphChecks.validateVertexCount(vertexCount);
 90	
 91	        List<List<Edge>> adjacency = new ArrayList<>(vertexCount);
 92	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 93	            adjacency.add(new ArrayList<>());
 94	        }
 95	        return new Graph(adjacency);
 96	    }
 97	
 98	    static Graph fromUndirectedConnections(int vertexCount, Connection... connections) {
 99	        Graph graph = withVertexCount(vertexCount);
100	        for (Connection connection : connections) {
101	            graph.addUndirectedConnection(connection);
102	        }
103	        return graph;
104	    }
105	
106	    void addUndirectedEdge(int u, int v, int weight) {
107	        addUndirectedConnection(Connection.of(u, v, weight));
108	    }
109	
110	    void addDirectedConnection(Connection connection) {
111	        validateConnection(connection);
112	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
113	    }
114	
115	    List<Edge> neighborsOf(int vertex) {
116	        GraphChecks.validateVertex(vertex, vertexCount(), "vertex");
117	        return adjacency.get(vertex);
118	    }
119	
120	    int vertexCount() {
121	        return adjacency.size();
122	    }
123	
124	    void validateSource(int source) {
125	        GraphChecks.validateVertex(source, vertexCount(), "src");
126	    }
127	
128	    private void addUndirectedConnection(Connection connection) {
129	        validateConnection(connection);
130	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
131	        addDirectedEdgeUnchecked(connection.to, connection.from, connection.weight);
132	    }
133	
134	    private void addDirectedEdgeUnchecked(int from, int to, int weight) {
135	        adjacency.get(from).add(new Edge(to, weight));
136	    }
137	
138	    private void validateConnection(Connection connection) {
139	        if (connection == null) {
140	            throw new IllegalArgumentException("Connection must not be null");
141	        }
142	
143	        GraphChecks.validateVertex(connection.from, vertexCount(), "from");
144	        GraphChecks.validateVertex(connection.to, vertexCount(), "to");
145	        GraphChecks.validateWeight(connection.weight);
146	    }
147	}
