149	final class LegacyGraphAdapter {
150	    static final int DESTINATION_INDEX = 0;
151	    static final int WEIGHT_INDEX = 1;
152	    static final int EDGE_FIELD_COUNT = 2;
153	
154	    private LegacyGraphAdapter() {
155	    }
156	
157	    static void addUndirectedEdge(ArrayList<ArrayList<int[]>> adj, int u, int v, int weight) {
158	        validateAdjacencyList(adj);
159	        GraphChecks.validateVertex(u, adj.size(), "u");
160	        GraphChecks.validateVertex(v, adj.size(), "v");
161	        GraphChecks.validateWeight(weight);
162	
163	        adj.get(u).add(edge(v, weight));
164	        adj.get(v).add(edge(u, weight));
165	    }
166	
167	    static Graph toGraph(ArrayList<ArrayList<int[]>> adj) {
168	        validateAdjacencyList(adj);
169	
170	        Graph graph = Graph.withVertexCount(adj.size());
171	        for (int from = 0; from < adj.size(); from++) {
172	            ArrayList<int[]> rawEdges = requireNeighborList(adj, from);
173	            for (int[] rawEdge : rawEdges) {
174	                graph.addDirectedConnection(toConnection(from, rawEdge, adj.size()));
175	            }
176	        }
177	        return graph;
178	    }
179	
180	    static int[] edge(int destination, int weight) {
181	        return new int[]{destination, weight};
182	    }
183	
184	    private static Connection toConnection(int from, int[] rawEdge, int vertexCount) {
185	        validateRawEdge(rawEdge, from);
186	
187	        int to = rawEdge[DESTINATION_INDEX];
188	        int weight = rawEdge[WEIGHT_INDEX];
189	        GraphChecks.validateVertex(to, vertexCount, "neighbor");
190	        GraphChecks.validateWeight(weight);
191	        return Connection.of(from, to, weight);
192	    }
193	
194	    private static ArrayList<int[]> requireNeighborList(ArrayList<ArrayList<int[]>> adj, int vertex) {
195	        ArrayList<int[]> neighbors = adj.get(vertex);
196	        if (neighbors == null) {
197	            throw new IllegalArgumentException(
198	                    "Adjacency list contains a null neighbor list at vertex " + vertex);
199	        }
200	        return neighbors;
201	    }
202	
203	    private static void validateAdjacencyList(ArrayList<ArrayList<int[]>> adj) {
204	        if (adj == null) {
205	            throw new IllegalArgumentException("Adjacency list must not be null");
206	        }
207	    }
208	
209	    private static void validateRawEdge(int[] rawEdge, int fromVertex) {
210	        if (rawEdge == null || rawEdge.length < EDGE_FIELD_COUNT) {
211	            throw new IllegalArgumentException(
212	                    "Edge at vertex " + fromVertex + " must contain destination and weight");
213	        }
214	    }
215	}
