227	final class Distances {
228	    private static final int UNREACHABLE = Integer.MAX_VALUE;
229	
230	    private final int[] values;
231	
232	    private Distances(int[] values) {
233	        this.values = values;
234	    }
235	
236	    static Distances forSource(int vertexCount, int source) {
237	        int[] values = new int[vertexCount];
238	        Arrays.fill(values, UNREACHABLE);
239	        values[source] = 0;
240	        return new Distances(values);
241	    }
242	
243	    boolean isStale(QueueEntry entry) {
244	        return entry.distance != values[entry.vertex];
245	    }
246	
247	    boolean tryUpdate(int vertex, int nextDistance) {
248	        if (nextDistance >= values[vertex]) {
249	            return false;
250	        }
251	
252	        values[vertex] = nextDistance;
253	        return true;
254	    }
255	
256	    ArrayList<Integer> toList() {
257	        ArrayList<Integer> result = new ArrayList<>(values.length);
258	        for (int distance : values) {
259	            result.add(distance);
260	        }
261	        return result;
262	    }
263	}
