265	final class ShortestPathSolver {
266	    private final Graph graph;
267	    private final Distances distances;
268	    private final PriorityQueue<QueueEntry> minHeap;
269	
270	    private ShortestPathSolver(Graph graph, int source) {
271	        this.graph = graph;
272	        this.distances = Distances.forSource(graph.vertexCount(), source);
273	        this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
274	        minHeap.offer(new QueueEntry(0, source));
275	    }
276	
277	    static Distances solve(Graph graph, int source) {
278	        return new ShortestPathSolver(graph, source).run();
279	    }
280	
281	    private Distances run() {
282	        while (!minHeap.isEmpty()) {
283	            QueueEntry current = minHeap.poll();
284	            if (distances.isStale(current)) {
285	                continue;
286	            }
287	
288	            relaxNeighborsOf(current);
289	        }
290	        return distances;
291	    }
292	
293	    private void relaxNeighborsOf(QueueEntry current) {
294	        for (Edge edge : graph.neighborsOf(current.vertex)) {
295	            tryRelax(current, edge);
296	        }
297	    }
298	
299	    private void tryRelax(QueueEntry current, Edge edge) {
300	        int nextDistance = GraphChecks.addDistances(current.distance, edge.weight);
301	        if (distances.tryUpdate(edge.to, nextDistance)) {
302	            minHeap.offer(new QueueEntry(nextDistance, edge.to));
303	        }
304	    }
305	}
