307	final class GraphChecks {
308	    private GraphChecks() {
309	    }
310	
311	    static void validateVertexCount(int vertexCount) {
312	        if (vertexCount < 0) {
313	            throw new IllegalArgumentException("Vertex count must be non-negative");
314	        }
315	    }
316	
317	    static void validateVertex(int vertex, int vertexCount, String label) {
318	        if (vertex < 0 || vertex >= vertexCount) {
319	            throw new IllegalArgumentException(label + " vertex out of range: " + vertex);
320	        }
321	    }
322	
323	    static void validateWeight(int weight) {
324	        if (weight < 0) {
325	            throw new IllegalArgumentException("Dijkstra's algorithm requires non-negative edge weights");
326	        }
327	    }
328	
329	    static int addDistances(int left, int right) {
330	        long sum = (long) left + right;
331	        if (sum > Integer.MAX_VALUE) {
332	            throw new ArithmeticException("Shortest path exceeds supported integer range");
333	        }
334	        return (int) sum;
335	    }
336	}
